function solve(image, sr, sc, color) {
  const img = image.map(r => [...r]);
  const startColor = img[sr][sc];
  if (startColor === color) return img;
  function dfs(r, c) {
    if (r<0 || c<0 || r>=img.length || c>=img[0].length || img[r][c] !== startColor) return;
    img[r][c] = color;
    dfs(r+1,c); dfs(r-1,c); dfs(r,c+1); dfs(r,c-1);
  }
  dfs(sr, sc);
  return img;
}

function solve(image, sr, sc, color) {
  const img = image.map(r => [...r]);
  const orig = img[sr][sc];
  if (orig === color) return img;
  const q = [[sr, sc]]; img[sr][sc] = color;
  while (q.length) {
    const [r, c] = q.shift();
    for (const [dr, dc] of [[1,0],[-1,0],[0,1],[0,-1]]) {
      const nr = r + dr, nc = c + dc;
      if (nr>=0 && nc>=0 && nr<img.length && nc<img[0].length && img[nr][nc]===orig) {
        img[nr][nc] = color; q.push([nr, nc]);
      }
    }
  }
  return img;
}

